#!/usr/bin/env python3
"""Enhancement options from the concept boards (owner 2026-10-31): docs/ENHANCEMENT_OPTIONS.md from rf2_lowL_options.json and
rf2_shaftlink_options.json. GENERATED; options only, nothing adopted."""
import os, json
HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.dirname(HERE); RES = os.path.join(HERE, "results")

def main():
    lo = json.load(open(os.path.join(RES, "rf2_lowL_options.json"))); sl = json.load(open(os.path.join(RES, "rf2_shaftlink_options.json")))
    base = lo["options"][0]
    L = ["# Enhancement options: low-L TX, planar nulled RX, optical shaft link, hex shaft (generated by rf2/rf2_enhance_report.py; MODELED)", "",
         "Options only: nothing here is adopted. Every option is listed; a broken rule is marked BREAKS with the value and the limit (owner rule: nothing is excluded).",
         f"Basis: {lo['status']}. Noise {lo['noise_basis']}. Calibration: {lo['calibration']}.", "",
         "## 1-2. Coil wiring, switch, TXD position, separate planar RX", "",
         "| Option | L uH | I boost A | first gate us | runtime boost h | coin cm | 1 g cm | 0.1 g cm | flex mm | TJ C | breaks |", "|---|---|---|---|---|---|---|---|---|---|---|"]
    for o in lo["options"]:
        name = f"{o['N']} x {o['p']}, {o['switch']}" + (f", RX {o['sep_rx']}" if o["sep_rx"] else "") + (", TXD at 400 mm" if o["txd_at_400mm"] else "") + (", TX strips on 2 layers" if o.get("tx_strips_2layer") else "")
        brk = "; ".join(f"BREAKS {r['rule']} ({r['value']} vs {r['limit']})" for r in o["rule_rows"] if not r["ok"]) or "-"
        if "depth_cm" not in o:
            L.append(f"| {name} | {o['L_uH']} | {o['I_boost']} | - | - | - | - | - | {o['flex_width_mm']} | - | NOT REACHABLE: {o['why_not']}; {brk} |"); continue
        d = o["depth_cm"]
        L.append(f"| {name} | {o['L_uH']} | {o['I_boost']} | {o['first_gate_us']} | {o['runtime_boost_h']} | {d['coin_25mm_silver']} | {d['gold_1g']} | {d['gold_0p1g']} | {o['flex_width_mm']} | {o['Tj_switch_boost_C']} | {brk} |")
    rx = next(o for o in lo["options"] if o["sep_rx"] and o["N"] == 7 and str(o["sep_rx"]).startswith("40"))["rx"]
    L += ["", f"Planar RX example (with the 7 x 4 TX): {rx}", "",
          "What the numbers say:",
          f"- The cheapest gain is the switch: NTBG080N120SC1 (80 mohm) instead of C3M0280090J (280 mohm) lifts continuous-boost runtime from {base['runtime_boost_h']} h; moving the TXD to s 400 mm adds more (table rows 2-4). Cost: Coss 79 pF adds about 0.6 us to the first gate.",
          "- Fewer turns with parallel strands (same copper, same comb) cut L by up to 28 x: the first gate drops from 16 us to 5-10 us and 0.1 g-class gold reads 30-45 % deeper, but coins and 1 g gold lose 9-25 % because the mono coil also receives with fewer turns. The current rises as 1/N: the cord-flex TX strips, the switch and its heat set the limit.",
          "- A separate nulled planar RX restores a fast gate whatever the TX does (RX settles in tens of ns, 0.1 mm misplacement leaves 0.2-0.4 % of the coupling), but its smaller area costs coin depth against the 26-turn rim coil.",
          "", "## 3. Optical link up the shaft", ""] + [f"- {f}" for f in sl["optical"]["findings"]] + [
          "", f"Numbers: {{k: v for k, v in sl['optical'].items() if k != 'findings'}}".format() if False else f"Numbers: { {k: v for k, v in sl['optical'].items() if k != 'findings'} }", "",
          "## 4. Hexagonal shaft, central bore, flex on the flats, long flex boards", ""] + [f"- {f}" for f in sl["hex"]["findings"]] + [
          "", "| Profile set | across flats mm | tubes g | tip sag mm | inner flats |", "|---|---|---|---|---|"] + [
          f"| {k} | {v['across_flats_mm']} | {v['tubes_g']} | {v['tip_sag_mm']} | {v['n_flats']} x {v['inner_flat_mm']} mm |" for k, v in sl["hex"].items() if k in ("square", "hex_same_af", "hex_equal_mass")] + [
          "", f"Lane groups on faces: {sl['hex']['lane_groups_on_faces']}", f"Central bore: {sl['hex']['central_bore']}", f"Long flex boards: {sl['hex']['long_flex_boards']}", "",
          "## Rule rows raised (also in docs/RULE_NEAR_MISSES.md)", ""] + [f"- {r['rule']}: {r['value']} vs {r['limit']} -> {'ok' if r['ok'] else 'BREAKS'}" for r in sl["rule_rows"]] + [
          "", "Files: rf2/results/shaftlink_*.stl, rf2/results/shaftlink_hex.step (hex telescope section with the central bore hub, POF, flex on three faces, long boards outside)."]
    open(os.path.join(ROOT, "docs", "ENHANCEMENT_OPTIONS.md"), "w").write("\n".join(L) + "\n"); print("written"); return True

if __name__ == "__main__": main()
